    m = {'sincos': [np.sin(k * q), np.cos(k * q)], 'tanh': [np.tanh(k * q)], 'ratio': [q / (1 + (k * q) ** 2), 1 / (1 + (k * q) ** 2)], 'squash': [q / np.sqrt(1 + (k * q) ** 2)], 'warp': [q + k * q * q], 'raw': []}[kind]
    return [q] + m

def quad(q):
    from sklearn.preprocessing import PolynomialFeatures
    return PolynomialFeatures(2).fit_transform(q)

def loo(f, v):
    h = f @ np.linalg.pinv(f)
    return np.sqrt(np.mean(((h @ v - v) / np.maximum(1 - h.diagonal(), 1e-09)[:, None]) ** 2))
